values ('ap_physics_c_mechanics', 2, '2.3', array['2.3']::text[], 'formula', 'Newton''s third law', '\vec{F}_{A\ on\ B}=-\vec{F}_{B\ on\ A}', '[]'::jsonb, NULL, 'The paired forces act on different objects, so they never cancel in a single object''s free-body diagram.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-010; ced=2.3.A.1 "paired forces that each exerts on the other"')
