values ('ap_physics_c_mechanics', 2, '2.4', array['2.4', '2.5']::text[], 'formula', 'Net force and translational equilibrium', '\vec{F}_{net}=\sum_i \vec{F}_i = 0', '[]'::jsonb, NULL, 'Net force is the vector sum of all forces exerted on the system. Translational equilibrium is the case where that sum is zero, so velocity stays constant. Forces can balance in one dimension and not in another, and velocity changes only along the unbalanced direction.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r2-002; ced=2.4.A.1 "The net force on a system is the vector sum of all forces exerted on the system"; 2.4.A.2 "Translational equilibrium is the configuration of forces such that the net force exerted on a system')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.4', array['2.4']::text[], 'convention', 'Newton''s first law', 'If the net force exerted on a system is zero, the velocity of that system remains constant.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-015; ced=2.4.A.3 "velocity of that system will remain constant"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.5', array['2.5', '2.9', '2.10']::text[], 'formula', 'Newton''s second law', '\vec{a}_{sys}=\frac{\sum\vec{F}}{m_{sys}}=\frac{\vec{F}_{net}}{m_{sys}}', '[]'::jsonb, NULL, 'The acceleration is that of the system''s center of mass, and it points in the direction of the net force.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-018; ced=2.5.A.2 "acceleration of a system''s center of mass has a magnitude proportional to the magnitude of the net force"')
