values ('ap_physics_c_mechanics', 2, '2.5', array['2.5']::text[], 'convention', 'When the center-of-mass velocity changes', 'The velocity of a system''s center of mass changes only if a nonzero net external force is exerted on the system.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-019; ced=2.5.A.3 "only change if a nonzero net external force"')
