values ('ap_physics_c_mechanics', 2, '2.6', array['2.6']::text[], 'vocabulary', 'Equivalence principle', 'An observer in a noninertial reference frame cannot distinguish between an object''s apparent weight and the gravitational force exerted on it by a gravitational field.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-026; ced=2.6.C.4 "The equivalence principle states"')
