insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.6', array['2.6']::text[], 'formula', 'Gravitational field strength', '|\vec{g}|=\frac{|\vec{F}_g|}{m}=\frac{GM}{r^2}', '[]'::jsonb, NULL, 'M is the mass of the system creating the field and m is the test object. When gravity is the only force on an object, its acceleration in m/s^2 is numerically equal to g in N/kg at that location.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r2-003; ced=2.6.A.2.i "The magnitude of the gravitational field created by a system of mass M at a point in space is equal to the ratio of the gravitational force... to the mass of the test object"; 2.6.A.2.ii')
