insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.6', array['2.6']::text[], 'vocabulary', 'Inertial mass vs. gravitational mass', 'Inertial mass (inertia) determines how much an object''s motion resists change when interacting with another object; gravitational mass is related to the attractive force between two systems with mass; the two are experimentally verified to be equivalent.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-027; ced=2.6.D.1-2.6.D.3')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
