insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.6', array['2.6']::text[], 'convention', 'When gravitational force is constant', 'If the gravitational force between two systems'' centers of mass changes negligibly as their relative position changes, it can be treated as constant between the initial and final positions.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-023; ced=2.6.B.1 "can be considered constant at all points"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.7', array['2.7']::text[], 'convention', 'Direction and dependence of kinetic friction', 'Kinetic friction opposes each surface''s motion relative to the other, and does not depend on the contact surface area; the coefficient depends on the surface materials.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-032; ced=2.7.A.1.i-2.7.A.1.ii; 2.7.A.2.i')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.7', array['2.7']::text[], 'formula', 'Kinetic friction magnitude', 'F_{f,k}=\mu_k F_N', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-030; ced=2.7.A.2 "product of the normal force ... and the coefficient of kinetic friction"')
