insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.7', array['2.7', '2.10']::text[], 'vocabulary', 'Normal force', 'The normal force is the perpendicular component of the force a surface exerts on an object in contact with it, directed away from the surface.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-031; ced=2.7.A.2.ii "perpendicular component of the force exerted on an object by the surface"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.7', array['2.7', '2.10']::text[], 'formula', 'Static friction (inequality and maximum)', 'F_{f,s}\le \mu_s F_N,\qquad F_{f,s,max}=\mu_s F_N', '[]'::jsonb, NULL, 'Static friction is an inequality that takes whatever value and direction prevents slipping; use the equality only at the slipping threshold.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-033; ced=2.7.B.2 "adopts the value and direction required to prevent an object from slipping"; 2.7.B.2.ii')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.7', array['2.7']::text[], 'convention', 'Static versus kinetic coefficient', 'The coefficient of static friction is typically greater than the coefficient of kinetic friction for a given pair of surfaces.', '[]'::jsonb, NULL, 'The CED says "typically," not always.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-034; ced=2.7.B.3 "typically greater than the coefficient of kinetic friction"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.8', array['2.8']::text[], 'formula', 'Hooke''s law', '\vec{F}_s=-k\,\Delta\vec{x}', '[]'::jsonb, NULL, 'Δx is measured from the spring''s relaxed length; the force is directed toward the equilibrium position of the object-spring system.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-035; ced=2.8.A.2 "Hooke''s law"; 2.8.A.3 "directed toward the equilibrium position"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.8', array['2.8']::text[], 'vocabulary', 'Ideal spring', 'An ideal spring has negligible mass and exerts a force proportional to the change in its length from its relaxed length; a nonideal spring has nonnegligible mass or a force not proportional to that change.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-036; ced=2.8.A.1 "An ideal spring has negligible mass"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.8', array['2.8']::text[], 'formula', 'Springs in parallel', 'k_{eq}=\sum_i k_i=k_1+k_2+\cdots', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-038; ced=2.8.B.1.iii "sum of the individual spring constants"')
