insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.8', array['2.8']::text[], 'formula', 'Springs in series', '\frac{1}{k_{eq}}=\sum_i\frac{1}{k_i}=\frac{1}{k_1}+\frac{1}{k_2}+\cdots', '[]'::jsonb, NULL, 'k_eq in series is smaller than the smallest individual spring constant. Only pure series or pure parallel combinations are expected, not mixed.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-037; ced=2.8.B.1.i-2.8.B.1.ii and Boundary Statement')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.9', array['2.9']::text[], 'formula', 'Resistive force', '\vec{F}_r=-k\vec{v}', '[]'::jsonb, NULL, 'A resistive force is velocity-dependent and opposite the object''s velocity.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-039; ced=2.9.A.1 "velocity-dependent force in the opposite direction of an object''s velocity"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.9', array['2.9']::text[], 'list_sequence', 'Solving motion under a resistive force', 'Steps for finding velocity, position, and acceleration of an object under a resistive force such as F_r = -kv.', '[{"label": "1", "meaning": "Apply Newton''s second law to the object with the resistive force, which gives a differential equation for velocity."}, {"label": "2", "meaning": "Use separation of variables to solve for the velocity."}, {"label": "3", "meaning": "Integrate over the proper limits of integration."}, {"label": "4", "meaning": "With velocity known as a function of time, use initial conditions and calculus to get position or acceleration."}, {"label": "5", "meaning": "Check the result: for F_r = -kv, position, velocity, and acceleration are exponential in time, with asymptotes set by the initial conditions and the forces exerted."}, {"label": "6", "meaning": "For terminal velocity, the maximum speed under a constant force and an opposing resistive force, set the net force equal to zero."}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r2-004; ced=2.9.A.2 "results in a differential equation for velocity"; 2.9.A.2.i "method of separation of variables"; 2.9.A.3 "The terminal condition is reached when the net force exerted on the object is zero"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.9', array['2.9']::text[], 'vocabulary', 'Terminal velocity', 'Terminal velocity is the maximum speed achieved by an object under a constant force and an opposing resistive force, reached when the net force on the object is zero.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-041; ced=2.9.A.3 "The terminal condition is reached when the net force exerted on the object is zero"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.10', array['2.10']::text[], 'formula', 'Centripetal acceleration', 'a_c=\frac{v^2}{r}', '[]'::jsonb, NULL, 'Directed toward the center of the circular path; it can come from one force, several forces, or force components, not a separate extra force.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-042; ced=2.10.A.1.i "ratio of the object''s tangential speed squared to the radius"; 2.10.A.2')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.10', array['2.10']::text[], 'formula', 'Kepler''s third law (circular orbit)', 'T^2=\frac{4\pi^2}{GM}R^3', '[]'::jsonb, NULL, 'Kepler''s first and second laws are not expected; the centripetal acceleration comes only from gravitational attraction by the central body.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-047; ced=2.10.B.1 "centripetal acceleration is caused only by gravitational attraction"; Boundary Statement')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.10', array['2.10']::text[], 'formula', 'Minimum speed at top of a vertical loop', 'v=\sqrt{gr}', '[]'::jsonb, NULL, 'Valid only at the top of the loop, where gravity alone supplies the centripetal acceleration.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-044; ced=2.10.A.2.i "gravitational force is the only force that causes the centripetal acceleration"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.10', array['2.10']::text[], 'formula', 'Period and frequency in uniform circular motion', 'T=\frac{1}{f},\qquad T=\frac{2\pi r}{v}', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-046; ced=2.10.A.5.ii "T = 1/f"; 2.10.A.5.iii "the period is given by the derived equation"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.10', array['2.10']::text[], 'list_sequence', 'Sources of centripetal force in named cases', 'In each named case, identify which force or force components supply the centripetal acceleration toward the center of the circular path.', '[{"label": "Top of a vertical loop (minimum speed)", "meaning": "Gravity is the only force causing the centripetal acceleration, which gives v = \\sqrt{gr}."}, {"label": "Banked surface", "meaning": "Components of the static friction force and the normal force contribute to the net force producing centripetal acceleration."}, {"label": "Conical pendulum", "meaning": "A component of the tension contributes to the net force producing centripetal acceleration."}, {"label": "Satellite in circular orbit", "meaning": "Gravitational attraction alone causes the centripetal acceleration."}]'::jsonb, NULL, 'Centripetal force is not a separate force on a free-body diagram. Name the actual forces, or their components, that point toward the center.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r2-005; ced=2.10.A.2 "Centripetal acceleration can result from a single force, more than one force, or components of forces"; 2.10.A.2.i-iii; 2.10.B.1')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_c_mechanics', 2, '2.10', array['2.10']::text[], 'convention', 'Tangential and net acceleration', 'Tangential acceleration is the rate at which speed changes and is tangent to the circular path; the net acceleration is the vector sum of the centripetal and tangential accelerations.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-c-mechanics-reference-u1-u3-2026-10-10; candidate=ap_physics_c_mechanics-u2-r1-043; ced=2.10.A.3-2.10.A.4')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
